package testutils

import (
	"reflect"
	"strings"
	"testing"
	"time"
	"unsafe"

	fuzz "github.com/google/gofuzz"
	"github.com/stretchr/testify/assert"
)

// FuzzOptions holds the configuration used by RunMapperFuzzTest. It is populated
// by applying the FuzzOption functional options passed to RunMapperFuzzTest.
type FuzzOptions struct {
	// customFuncs are additional fuzzer functions registered on the fuzzer,
	// e.g. domain-specific enum fuzzers.
	customFuncs []interface{}
	// excludedFields are struct field names that should be zeroed on both the
	// original and the round-tripped value before comparison.
	excludedFields []string
	// nilChance is the probability (0..1) that the fuzzer leaves a pointer nil.
	nilChance float64
	// iterations is the number of round-trip fuzz iterations to perform.
	iterations int
}

// FuzzOption is a functional option for configuring RunMapperFuzzTest behavior.
type FuzzOption func(*FuzzOptions)

// WithCustomFuncs returns a FuzzOption that registers the provided custom fuzzer
// functions with the underlying fuzzer. Each function must match the signature
// expected by gofuzz, i.e. func(*T, fuzz.Continue). Callers use this to register
// domain-specific enum fuzzers (e.g. WithScheduleEnumFuzzers).
func WithCustomFuncs(funcs ...interface{}) FuzzOption {
	return func(o *FuzzOptions) {
		o.customFuncs = append(o.customFuncs, funcs...)
	}
}

// WithExcludedFields returns a FuzzOption that adds the provided field names to
// the set of fields cleared before comparison. This is useful for fields that
// are not expected to survive a round-trip (e.g. fields with no external
// representation).
func WithExcludedFields(fields ...string) FuzzOption {
	return func(o *FuzzOptions) {
		o.excludedFields = append(o.excludedFields, fields...)
	}
}

// WithNilChance returns a FuzzOption that sets the probability that the fuzzer
// leaves pointers nil. The value must be in the range [0, 1].
func WithNilChance(chance float64) FuzzOption {
	return func(o *FuzzOptions) {
		o.nilChance = chance
	}
}

// WithIterations returns a FuzzOption that sets the number of round-trip fuzz
// iterations to perform.
func WithIterations(n int) FuzzOption {
	return func(o *FuzzOptions) {
		o.iterations = n
	}
}

// defaultFuzzFuncs returns the fuzzer functions that are always applied,
// regardless of caller-provided options. These cover the common time types so
// that fuzzed values round-trip cleanly (avoiding monotonic clock readings and
// non-UTC locations that would otherwise break equality comparisons).
func defaultFuzzFuncs() []interface{} {
	return []interface{}{
		func(t *time.Time, c fuzz.Continue) {
			if c.Intn(10) < 3 {
				*t = time.Time{}
				return
			}
			*t = time.Unix(c.Int63n(4102444800), c.Int63n(1e9)).UTC()
		},
		func(d *time.Duration, c fuzz.Continue) {
			if c.Intn(10) < 3 {
				*d = 0
				return
			}
			*d = time.Duration(c.Int63n(int64(24 * time.Hour)))
		},
	}
}

// RunMapperFuzzTest runs a round-trip fuzz test for a mapper pair. It repeatedly
// fuzzes a value of TInternal, passes it through fromFunc then toFunc, and
// asserts that the result equals the original. Before comparing, protobuf- and
// mapper-internal fields (as well as any caller-specified excluded fields) are
// stripped from both values via clearExcludedFields.
//
// The default time fuzzers are always applied. Additional fuzzer functions and
// other behavior can be supplied via FuzzOption values.
func RunMapperFuzzTest[TInternal any, TExternal any](
	t *testing.T,
	fromFunc func(TInternal) TExternal,
	toFunc func(TExternal) TInternal,
	options ...FuzzOption,
) {
	t.Helper()

	opts := &FuzzOptions{
		nilChance:  0.3,
		iterations: 1000,
	}
	for _, opt := range options {
		opt(opts)
	}

	seed := time.Now().UnixNano()
	f := fuzz.NewWithSeed(seed).NilChance(opts.nilChance)
	f = f.Funcs(defaultFuzzFuncs()...)
	if len(opts.customFuncs) > 0 {
		f = f.Funcs(opts.customFuncs...)
	}

	defer func() {
		if t.Failed() {
			t.Logf("fuzz seed: %v", seed)
		}
	}()

	for i := 0; i < opts.iterations; i++ {
		var orig TInternal
		f.Fuzz(&orig)

		result := toFunc(fromFunc(orig))

		clearExcludedFields(&orig, opts.excludedFields)
		clearExcludedFields(&result, opts.excludedFields)

		if !assert.Equalf(t, orig, result, "value did not survive round-tripping on iteration %v", i) {
			return // stop on first failure, the seed is logged for reproduction
		}
	}
}

// clearExcludedFields recursively traverses obj (through any depth of pointer
// indirection) and zeroes out struct fields whose names start with "XXX_", are
// the protobuf-internal "sizeCache"/"unknownFields" fields, or are listed in
// excludedFields. Fields that do not match these criteria are left untouched.
//
// Nested value-type structs, slices of value-type structs (modified in place),
// and slices of pointer-type structs are all traversed recursively.
func clearExcludedFields(obj interface{}, excludedFields []string) {
	if obj == nil {
		return
	}
	excluded := make(map[string]struct{}, len(excludedFields))
	for _, name := range excludedFields {
		excluded[name] = struct{}{}
	}
	clearValue(reflect.ValueOf(obj), excluded)
}

// clearValue dereferences through any number of pointer/interface levels and
// dispatches on the underlying kind, recursing into structs and slice/array
// elements.
func clearValue(v reflect.Value, excluded map[string]struct{}) {
	for v.Kind() == reflect.Ptr || v.Kind() == reflect.Interface {
		if v.IsNil() {
			return
		}
		v = v.Elem()
	}

	switch v.Kind() {
	case reflect.Struct:
		clearStructFields(v, excluded)
	case reflect.Slice, reflect.Array:
		for i := 0; i < v.Len(); i++ {
			clearValue(v.Index(i), excluded)
		}
	}
}

// clearStructFields iterates over the fields of a struct value, zeroing those
// that match the exclusion criteria and recursing into the rest.
func clearStructFields(v reflect.Value, excluded map[string]struct{}) {
	t := v.Type()
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		name := t.Field(i).Name

		if shouldClearField(name, excluded) {
			zeroField(field)
			continue
		}

		clearValue(field, excluded)
	}
}

